using UnityEngine;
public class ColonyAnthill : MonoBehaviour
{ public Transform spawnPoint; public float spawnInterval = 4.5f; public float minInterval = 2.2f; public int maxAlive = 8; public GameObject raiderPrefab; ColonyHealth health; float timer; int spawned; Vector3 originalScale; void Awake() { originalScale = transform.localScale; health = GetComponent<ColonyHealth>(); if (spawnPoint == null) { var t = transform.Find("Spawn"); spawnPoint = t != null ? t : transform; } } public void ResetSpawner() { timer = 4f; spawned = 0; transform.localScale = originalScale; } void Update() { if (health != null && health.IsDead) { transform.localScale = Vector3.Lerp(transform.localScale, new Vector3(originalScale.x, originalScale.y * .18f, originalScale.z), Time.deltaTime * 3f); return; } var director = ColonyGameDirector.Instance; if (director == null || !director.IsPlaying || health == null || health.IsDead) { return; } timer -= Time.deltaTime; if (timer > 0f) { return; } if (director.AliveRaiders >= maxAlive || raiderPrefab == null) { timer = 0.4f; return; } Vector3 pos = spawnPoint.position + new Vector3(Random.Range(-1.2f, 1.2f), 0.2f, Random.Range(-0.4f, 0.8f)); var go = Instantiate(raiderPrefab, pos, spawnPoint.rotation); go.SetActive(true); director.RegisterRaider(go.GetComponent<ColonyRaiderAI>()); spawned++; float t = Mathf.Clamp01(spawned / 18f); timer = Mathf.Lerp(spawnInterval, minInterval, t); EventDispatcher.SendEvent(GameEventTypes.SpawnEventType.Spawned, gameObject.GetInstanceID(), go.GetInstanceID(), "Raider", pos); } }